INSERT INTO `article` (`id`, `image`, `title`, `publish_date`, `article_body`, `keywords`) VALUES
(1, 'https://cdns.klimg.com/kapanlagi.com/v5/i/channel/entertainment/KLlogo.png', '7 Potret Dapur Reza Artamevia yang Jarang Tersorot, Konsep Open Space - Dominasi Warna Putih', '2024-10-29 19:44:00', 'Reza Artamevia dikenal sebagai penyanyi yang juga dijuluki salah satu Diva Indonesia. Rumah pelantun Berharap Tak Berpisah tak lepas dari perhatian lantaran jarang tersorot.\nReza Artamevia memang jarang memperlihatkan home tour rumah pribadinya yang ditempati bersama sang anak. Terlebih, Aaliyah Massaid pernah mengungkapkan bahwa rumahnya tersebut menjadi zona tanpa vlog.\nKarena alasan inilah, tak banyak momen yang diunggah sang artis melalui akun media sosial pribadi terkait kediamannya. Meski begitu, Reza Artamevia sempat menunjukkan kediamannya yang jarang tersorot. Salah satunya, area dapur yang tidak kalah menarik perhatian. Penasaran seperti apa potret dapur Reza Artamevia? Selengkapnya cek di sini KLovers. Dapur Reza Artamevia ini juga dilengkapi dengan berbagai perabotan. Ada kulkas, peralatan rumah tangga, hingga perabotan lainnya yang tertata rapi. Seperti inilah potret dapur Reza Artamevia dengan beragam perabotannya. Beberapa bahan makanan hingga piring dan gelas tersimpan rapi pada rak-rak.Itulah potret dapur Reza Artamevia yang jarang tersorot. Kediaman Reza Artamevia ini terutama sudut dapurnya dapat juga menjadi inspirasi menentukan konsep dapur nyaman serta elegan. Terus ikuti berita terbaru seputar Reza Artamevia di sini. Kalau bukan sekarang, KapanLagi? Dapur rumah Reza Artamevia juga memiliki meja makan yang luas. Fakta menariknya, Thariq Halilintar pernah mengungkapkan sering menghabiskan waktu mengobrol dengan ibu mertua di meja makan rumah sang istri. Seperti inilah potret meja makan di dapur rumah Reza Artamevia yang luas sekaligus nyaman dilengkapi kursi berwarna putih. Hampir seluruh dapur ini didominasi warna putih, mulai dari dinding hingga lemari penyimpanan. Warna putih memberikan kesan bersih dan elegan. Lihatlah dalam potret ini, dapur di rumah Reza Artamevia yang terasa lebih lega serta terang. Meski Reza Artamevia dikenal sebagai sosok publik figur, potret bagian dalam rumahnya jarang dibagikan melalui akun media sosial. Tidak heran, area dapur kediamannya ini jarang tersorot. Seperti inilah potret dapur di rumah Reza Artamevia yang sempat terekam dalam vlog Thariq Halilintar. Reza Artamevia memiliki area dapur bersih yang berdesain minimalis. Seperti dalam potret ini, suasana yang nyaman dan hangat di sudut dapur rumah sang artis. Dapur ini memiliki jendela berbentuk kotak-kotak serta pintu yang terhubung menuju area outdoor. Reza Artamevia mengungkapkan kediamannya ini berkonsep open space. Termasuk, area dapur yang mengusung konsep serupa. Tidak heran, dapur ini terasa begitu lega yang juga terhubung dengan ruang tamu. Dengan konsep ruang terbuka ini, dapur terasa lebih menyatu dengan area lainnya. Sementara itu, area counter table dapur Reza Artamevia ini memiliki warna abu-abu. Sentuhan abu-abu ini menjadi aksen yang menarik pada dapur rumah sang artis. Di atasnya terdapat kabinet lemari dapur serta rak-rak. Lihatlah dalam potret ini, area counter table juga terdapat wastafel.', 'Reza Artamevia;;berita Reza Artamevia;;rumah Reza Artamevia;;Aktivitas Seleb;;Foto Instagram;;Konten Menarik;;Rumah Selebriti Indonesia;;Rumah Selebritis;;Trending;;'),
(2, 'https://cdns.klimg.com/kapanlagi.com/v5/i/channel/entertainment/KLlogo.png', 'Bikin Baper! Chicco Jerikho Ungkap Rasa Syukur Punya Pendamping Hidup Yang Luar Biasa Seperti Putri Marino', '2024-10-29 20:05:00', 'Siapa sangka sih kalau Putri Marino, aktris kece yang sering bikin baper di layar kaca, pernah merasa down banget? Dalam podcast terbaru bareng Denny Sumargo, istri Chicco Jerikho ini ngungkap sisi lain dari hidupnya yang jarang banget kita tahu. Ternyata, setelah menikah dan hamil, Putri sempat merasa kehilangan banget sama dunia akting yang udah jadi bagian dari hidupnya.\nBayangin aja, dari yang biasanya sibuk syuting dan menghadiri berbagai acara, tiba-tiba Putri harus fokus ngurus rumah dan keluarga. Perasaan iri dan minder pun nggak bisa dia hindari. \"Kok gue nggak kayak teman-teman yang masih bisa berkarya sih?\", mungkin itu pertanyaan yang sering terngiang di benaknya. Padahal, sebelum menikah, karier Putri lagi naik daun banget lho!\nNah, curhatan Putri ini bikin kita semua jadi paham kalau nggak semua kehidupan seleb itu selalu glamor. Ternyata, mereka juga punya perasaan yang sama kayak kita, kok. Putri Marino berhasil membuktikan kalau di balik senyum manisnya, ada perjuangan dan tantangan yang harus dia hadapi. Setelah curhatan Putri Marino dalam Podcast Denny Sumargo viral, banyak netizen yang iri sama Chicco Jerikho. Mereka penasaran banget gimana rasanya punya istri secantik dan secerdas Putri. Nah, Chicco pun menjawab dengan singkat tapi penuh makna, \\\"Rasanya BERUNTUNG.\\\" Jawaban Chicco ini bikin banyak orang baper dan semakin ngiri sama pasangan seleb yang satu ini.Jawaban singkat Chicco ini sebenarnya mengandung makna yang dalam. Selain karena Putri adalah sosok yang cantik dan cerdas, Chicco juga mengagumi perjuangan dan semangat juang istrinya. Putri adalah sosok yang kuat dan inspiratif, dan Chicco merasa beruntung bisa menjadi bagian dari hidup Putri. Siapa sangka, di balik senyum manisnya, Putri Marino pernah merasa insecure banget! Pasca meraih kesuksesan dengan film POSESIF dan memutuskan untuk vakum karena hamil, Putri jadi takut banget kalau-kalau dia bakal dilupain sama penonton. Bayangin aja, dari yang biasanya jadi pusat perhatian, tiba-tiba dia harus ngilang dari layar kaca. \\\"Duh, gimana kalau nanti ada artis baru yang lebih menarik perhatian?\\\" mungkin itu yang sering dipikirin Putri waktu itu. Padahal, semangat berkaryanya lagi membara banget lho!Ketakutan terbesar Putri adalah kehilangan identitasnya sebagai seorang aktris. Dia khawatir kalau-kalau setelah vakum, dia bakal kesulitan untuk kembali ke dunia hiburan. Apalagi, persaingan di industri hiburan kan semakin ketat. Putri takut kalau-kalau dia bakal ketinggalan dan nggak bisa lagi meraih kesuksesan seperti dulu. Dari seorang aktris yang sibuk syuting dan menghadiri berbagai acara, Putri harus beradaptasi jadi ibu rumah tangga. Awalnya sih nggak masalah, tapi lama-lama Putri mulai merasa ada yang kurang. Dia ngerasa kayak terjebak dalam rutinitas yang itu-itu aja, sementara teman-temannya lagi asyik mengejar mimpi. &ldquo;Aku di rumah doang, ngurus suami, aku hamil, aku pengin kayak teman-teman aku masih kerja, berkarya, aku pengin buktiin kalau aku bisa jadi aktor hebat, aku iri lihat teman-teman aku jalan-jalan sama temannya, aku iri lihat teman aku tiap bulan ngeluarin film baru,&rdquo; ujar Putri dalam Podcast Denny Sumargo. Dia kangen banget sama sensasi syuting, bertemu dengan kru film, dan berakting di depan kamera.Perubahan yang drastis ini bikin Putri sempat merasa kehilangan arah. Dia bingung mau ngapain lagi selain ngurus rumah dan anak. Putri merasa kayak ada bagian penting dari dirinya yang hilang. Untungnya, dengan dukungan dari keluarga dan suami, Putri akhirnya bisa bangkit dan menemukan kembali semangatnya untuk berkarya.', 'Chicco Jerikho;;Putri Marino;;Denny Sumargo;;Istri Chicco Jerikho;;Aktivitas Seleb;;Apa Kabar Seleb;;Kisah Viral Hari Ini;;'),
(3, 'https://cdns.klimg.com/kapanlagi.com/v5/i/channel/entertainment/KLlogo.png', 'Bikin Baper! Chicco Jerikho Ungkap Rasa Syukur Punya Pendamping Hidup Yang Luar Biasa Seperti Putri Marino', '2024-10-29 20:05:00', 'Siapa sangka sih kalau Putri Marino, aktris kece yang sering bikin baper di layar kaca, pernah merasa down banget? Dalam podcast terbaru bareng Denny Sumargo, istri Chicco Jerikho ini ngungkap sisi lain dari hidupnya yang jarang banget kita tahu. Ternyata, setelah menikah dan hamil, Putri sempat merasa kehilangan banget sama dunia akting yang udah jadi bagian dari hidupnya.\nBayangin aja, dari yang biasanya sibuk syuting dan menghadiri berbagai acara, tiba-tiba Putri harus fokus ngurus rumah dan keluarga. Perasaan iri dan minder pun nggak bisa dia hindari. \"Kok gue nggak kayak teman-teman yang masih bisa berkarya sih?\", mungkin itu pertanyaan yang sering terngiang di benaknya. Padahal, sebelum menikah, karier Putri lagi naik daun banget lho!\nNah, curhatan Putri ini bikin kita semua jadi paham kalau nggak semua kehidupan seleb itu selalu glamor. Ternyata, mereka juga punya perasaan yang sama kayak kita, kok. Putri Marino berhasil membuktikan kalau di balik senyum manisnya, ada perjuangan dan tantangan yang harus dia hadapi. Setelah curhatan Putri Marino dalam Podcast Denny Sumargo viral, banyak netizen yang iri sama Chicco Jerikho. Mereka penasaran banget gimana rasanya punya istri secantik dan secerdas Putri. Nah, Chicco pun menjawab dengan singkat tapi penuh makna, \\\"Rasanya BERUNTUNG.\\\" Jawaban Chicco ini bikin banyak orang baper dan semakin ngiri sama pasangan seleb yang satu ini.Jawaban singkat Chicco ini sebenarnya mengandung makna yang dalam. Selain karena Putri adalah sosok yang cantik dan cerdas, Chicco juga mengagumi perjuangan dan semangat juang istrinya. Putri adalah sosok yang kuat dan inspiratif, dan Chicco merasa beruntung bisa menjadi bagian dari hidup Putri. Siapa sangka, di balik senyum manisnya, Putri Marino pernah merasa insecur